#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <cstdint>

// ---------------------------------------------------------------
// Type aliases derived from params.yaml
// acm / eigenvalues: bits=22, signed=1, fraction=0
//   bits_per_component = 22+1 = 23
//   ap_fixed<23, 23-0> = ap_fixed<23,23>
// eigenvectors: bits=22, signed=1, fraction=20
//   bits_per_component = 23
//   ap_fixed<23, 23-20> = ap_fixed<23,3>
// max_iter / ite: bits=16, signed=0, fraction=0
//   bits_per_component = 16
//   ap_uint<16>
// ---------------------------------------------------------------

typedef ap_fixed<23, 23> acm_t;        // real or imag of A elements / eigenvalues
typedef ap_fixed<23,  3> evec_t;       // real or imag of eigenvector elements
typedef ap_uint<16>      iter_t;

static const int MAT_N = 10;

void kernel_top(
    // Input: A [10][10] complex  → real and imag planes
    acm_t  A_re[MAT_N][MAT_N],
    acm_t  A_im[MAT_N][MAT_N],
    // Input: max_iter (scalar)
    iter_t max_iter,
    // Output: eigenvalues [10] complex
    acm_t  eigenvalues_re[MAT_N],
    acm_t  eigenvalues_im[MAT_N],
    // Output: eigenvectors [10][10] complex
    evec_t eigenvectors_re[MAT_N][MAT_N],
    evec_t eigenvectors_im[MAT_N][MAT_N],
    // Output: iteration count
    iter_t &ite,
    // C-sim cycle proxy
    uint32_t &clock_cycles
);

#endif // KERNEL_H
