#include "kernel.h"
#include <cmath>
#include <cstring>

// ---------------------------------------------------------------
// Internal full-precision working types (double) so that the
// iterative Jacobi numerics stay accurate; only I/O ports use
// ap_fixed.
// ---------------------------------------------------------------

static const int N = MAT_N;

static void mat_mul_cc(
    double Ar[N][N], double Ai[N][N],
    double Br[N][N], double Bi[N][N],
    double Cr[N][N], double Ci[N][N])
{
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            double sr = 0.0, si = 0.0;
            for (int k = 0; k < N; k++) {
                sr += Ar[i][k]*Br[k][j] - Ai[i][k]*Bi[k][j];
                si += Ar[i][k]*Bi[k][j] + Ai[i][k]*Br[k][j];
            }
            Cr[i][j] = sr;
            Ci[i][j] = si;
        }
    }
}

// Multiply  C = A^H * B  (conjugate-transpose of A times B)
static void mat_mulH_cc(
    double Ar[N][N], double Ai[N][N],  // A (will be conjugated)
    double Br[N][N], double Bi[N][N],
    double Cr[N][N], double Ci[N][N])
{
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            double sr = 0.0, si = 0.0;
            for (int k = 0; k < N; k++) {
                // A^H[i][k] = conj(A[k][i]) = (Ar[k][i], -Ai[k][i])
                double ahr =  Ar[k][i];
                double ahi = -Ai[k][i];
                sr += ahr*Br[k][j] - ahi*Bi[k][j];
                si += ahr*Bi[k][j] + ahi*Br[k][j];
            }
            Cr[i][j] = sr;
            Ci[i][j] = si;
        }
    }
}

void kernel_top(
    acm_t  A_re[N][N],
    acm_t  A_im[N][N],
    iter_t max_iter,
    acm_t  eigenvalues_re[N],
    acm_t  eigenvalues_im[N],
    evec_t eigenvectors_re[N][N],
    evec_t eigenvectors_im[N][N],
    iter_t &ite,
    uint32_t &clock_cycles)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return

    clock_cycles = 0;

    // Copy inputs to working double arrays
    double Ar[N][N], Ai[N][N];
    double Vr[N][N], Vi[N][N];

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            Ar[i][j] = (double)A_re[i][j];
            Ai[i][j] = (double)A_im[i][j];
            Vr[i][j] = (i == j) ? 1.0 : 0.0;
            Vi[i][j] = 0.0;
        }
    }

    int z = 0;
    int mi = (int)max_iter;

    JACOBI_OUTER: for (z = 0; z < mi; z++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=1000

        // --- find off-diagonal element with largest magnitude ---
        double off_diag_max = 0.0;
        int p = 0, q = 1;

        FIND_MAX_I: for (int i = 0; i < N; i++) {
            FIND_MAX_J: for (int j = i + 1; j < N; j++) {
                double re = Ar[i][j];
                double im = Ai[i][j];
                double mag = re*re + im*im; // compare squared magnitudes
                double cur = off_diag_max * off_diag_max;
                if (mag > cur) {
                    off_diag_max = sqrt(mag);
                    p = i;
                    q = j;
                }
                clock_cycles++;
            }
        }

        if (off_diag_max < 1e-8) {
            break;
        }

        // --- compute rotation parameters ---
        double a_pp_r = Ar[p][p], a_pp_i = Ai[p][p];
        double a_qq_r = Ar[q][q], a_qq_i = Ai[q][q];
        double a_pq_r = Ar[p][q], a_pq_i = Ai[p][q];

        double abs_apq = sqrt(a_pq_r*a_pq_r + a_pq_i*a_pq_i);

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        // a_pp and a_qq are real (diagonal of Hermitian after previous step)
        double denom = a_pp_r - a_qq_r;
        double theta = 0.5 * atan2(2.0 * abs_apq, denom);

        // phi = -angle(a_pq)
        double phi = -atan2(a_pq_i, a_pq_r);

        double cos_t = cos(theta);
        double sin_t = sin(theta);
        double cos_phi = cos(phi);
        double sin_phi = sin(phi);

        // U[p][p] = cos(theta)  (real)
        // U[p][q] = sin(theta)*exp(-j*phi)
        // U[q][p] = sin(theta)*exp(+j*phi)
        // U[q][q] = -cos(theta) (real, note: Python sets this to -cos)

        double Ur[N][N], Ui[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Ur[i][j] = (i == j) ? 1.0 : 0.0;
                Ui[i][j] = 0.0;
            }
        }
        Ur[p][p] =  cos_t;         Ui[p][p] = 0.0;
        Ur[p][q] =  sin_t * cos_phi; Ui[p][q] = -sin_t * sin_phi; // sin*exp(-j*phi)
        Ur[q][p] =  sin_t * cos_phi; Ui[q][p] =  sin_t * sin_phi; // sin*exp(+j*phi)
        Ur[q][q] = -cos_t;         Ui[q][q] = 0.0;

        // A = U^H * A * U
        double tmp_r[N][N], tmp_i[N][N];
        double new_Ar[N][N], new_Ai[N][N];

        mat_mulH_cc(Ur, Ui, Ar, Ai, tmp_r, tmp_i);
        mat_mul_cc (tmp_r, tmp_i, Ur, Ui, new_Ar, new_Ai);

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Ar[i][j] = new_Ar[i][j];
                Ai[i][j] = new_Ai[i][j];
            }
        }
        Ar[p][q] = 0.0; Ai[p][q] = 0.0;
        Ar[q][p] = 0.0; Ai[q][p] = 0.0;

        // V = V * U
        double new_Vr[N][N], new_Vi[N][N];
        mat_mul_cc(Vr, Vi, Ur, Ui, new_Vr, new_Vi);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Vr[i][j] = new_Vr[i][j];
                Vi[i][j] = new_Vi[i][j];
            }
        }

        clock_cycles++;
    }

    // --- write outputs ---
    for (int i = 0; i < N; i++) {
        eigenvalues_re[i] = (acm_t)Ar[i][i];
        eigenvalues_im[i] = (acm_t)Ai[i][i];
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            eigenvectors_re[i][j] = (evec_t)Vr[i][j];
            eigenvectors_im[i][j] = (evec_t)Vi[i][j];
        }
    }

    ite = (iter_t)z;
}
