#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include "kernel.h"

// Exact I/O paths from context
static const char IO_DIR[]  = "/home/mbenton/verilog_rapid_prototyping/conversion_017/eig_10_io/";
static const char SIM_DIR[] = "/home/mbenton/verilog_rapid_prototyping/conversion_017/build/sim/";

static const int N = MAT_N;

int main()
{
    // ------------------------------------------------------------------
    // Allocate port arrays
    // ------------------------------------------------------------------
    acm_t  A_re[N][N], A_im[N][N];
    iter_t max_iter;
    acm_t  eigenvalues_re[N], eigenvalues_im[N];
    evec_t eigenvectors_re[N][N], eigenvectors_im[N][N];
    iter_t ite;
    uint32_t clock_cycles = 0;

    // ------------------------------------------------------------------
    // Read in_A.txt  (call index 0 = first 10*10 = 100 complex pairs)
    // Format: each line has two tokens: real imag
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_A.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re = 0.0, im = 0.0;
                if (fscanf(fp, "%lf %lf", &re, &im) != 2) {
                    fprintf(stderr, "Read error in %s at [%d][%d]\n", path, i, j);
                    fclose(fp); return 1;
                }
                A_re[i][j] = (acm_t)re;
                A_im[i][j] = (acm_t)im;
            }
        }
        fclose(fp);
    }

    // ------------------------------------------------------------------
    // Read in_max_iter.txt (call index 0 = first scalar)
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_max_iter.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }

        long long val = 0;
        if (fscanf(fp, "%lld", &val) != 1) {
            fprintf(stderr, "Read error in %s\n", path);
            fclose(fp); return 1;
        }
        max_iter = (iter_t)val;
        fclose(fp);
    }

    // ------------------------------------------------------------------
    // Call kernel
    // ------------------------------------------------------------------
    kernel_top(
        A_re, A_im,
        max_iter,
        eigenvalues_re, eigenvalues_im,
        eigenvectors_re, eigenvectors_im,
        ite,
        clock_cycles
    );

    // ------------------------------------------------------------------
    // Write out_0.txt  (eigenvalues, complex, shape [10])
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_0.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        for (int i = 0; i < N; i++) {
            fprintf(fp, "%.10f %.10f\n",
                    (double)eigenvalues_re[i],
                    (double)eigenvalues_im[i]);
        }
        fclose(fp);
    }

    // ------------------------------------------------------------------
    // Write out_1.txt  (eigenvectors, complex, shape [10][10])
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_1.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                fprintf(fp, "%.10f %.10f\n",
                        (double)eigenvectors_re[i][j],
                        (double)eigenvectors_im[i][j]);
            }
        }
        fclose(fp);
    }

    // ------------------------------------------------------------------
    // Write out_2.txt  (ite, scalar integer)
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_2.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        fprintf(fp, "%u\n", (unsigned)ite);
        fclose(fp);
    }

    // ------------------------------------------------------------------
    // Write clock_cycles.txt
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sclock_cycles.txt", SIM_DIR);
        FILE *fp = fopen(path, "w");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        fprintf(fp, "%u\n", clock_cycles);
        fclose(fp);
    }

    printf("kernel_top done: ite=%u  clock_cycles=%u\n",
           (unsigned)ite, clock_cycles);
    return 0;
}
